function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(61001);
var T0=Date.now();
var J=20,RG=3;
var regs=[];for(var i=0;i<RG;i++)regs.push({cap:50+Math.floor(R()*100),used:0});
var jobs=[];for(var i=0;i<J;i++)jobs.push(5+Math.floor(R()*40));
var placed=0;
jobs.forEach(function(d){var r=regs.find(function(x){return x.cap-x.used>=d;});if(r){r.used+=d;placed++;}});
var util=regs.reduce(function(a,x){return a+x.used;},0)/regs.reduce(function(a,x){return a+x.cap;},0);
console.log(JSON.stringify({id:"JAH-APX61-000001",ok:true,metrics:{jobs:J,regions:RG,placed:placed,unplaced:J-placed,utilization:+util.toFixed(3)},ms:Date.now()-T0}));

